export function getBook(id: string) {
  return BOOKS.find(b => b.id === id);
}

export function getChapter(bookId: string, chapter: number): string[] | undefined {
  return BIBLE[bookId]?.[chapter];
}

export function getAllVerses(): { bookId: string; chapter: number; verse: number; text: string }[] {
  const result: { bookId: string; chapter: number; verse: number; text: string }[] = [];
  for (const [bookId, chapters] of Object.entries(BIBLE)) {
    for (const [chapterStr, verses] of Object.entries(chapters)) {
      const chapter = Number(chapterStr);
      verses.forEach((text, idx) => {
        result.push({ bookId, chapter, verse: idx + 1, text: text.trim() });
      });
    }
  }
  return result;
}
